function digitHints(secret: string, guess: string): number[] {
  const n = secret.length;
  const used = new Array(n).fill(false);
  let exact = 0, misplaced = 0;
  for (let i = 0; i < n; i++) if (secret[i] === guess[i]) { used[i] = true; exact++; }
  for (let i = 0; i < n; i++) {
    if (secret[i] === guess[i]) continue;
    for (let j = 0; j < n; j++) {
      if (!used[j] && secret[j] === guess[i]) { used[j] = true; misplaced++; break; }
    }
  }
  return [exact, misplaced];
}

