class Solution:
    def digitHints(self, secret: str, guess: str) -> List[int]:
        n = len(secret)
        used = [secret[i] == guess[i] for i in range(n)]
        exact = sum(used)
        misplaced = 0
        for i in range(n):
            if secret[i] == guess[i]:
                continue
            for j in range(n):
                if not used[j] and secret[j] == guess[i]:
                    used[j] = True
                    misplaced += 1
                    break
        return [exact, misplaced]

