function digitHints(secret: string, guess: string): number[] {
  const s = new Array(10).fill(0), g = new Array(10).fill(0);
  let exact = 0;
  for (let i = 0; i < secret.length; i++) {
    if (secret[i] === guess[i]) exact++;
    else { s[+secret[i]]++; g[+guess[i]]++; }
  }
  let misplaced = 0;
  for (let d = 0; d < 10; d++) misplaced += Math.min(s[d], g[d]);
  return [exact, misplaced];
}

