class Solution:
    def digitHints(self, secret: str, guess: str) -> List[int]:
        s, g = [0] * 10, [0] * 10
        exact = 0
        for a, b in zip(secret, guess):
            if a == b:
                exact += 1
            else:
                s[int(a)] += 1
                g[int(b)] += 1
        return [exact, sum(min(x, y) for x, y in zip(s, g))]

